html:
{%- set address = frappe.get_doc("Address", doc.billing_address) if doc.billing_address else None -%}
<style>
	.ec h2 { margin: 0 0 4px; }
	.ec .muted { color: #6b7280; }
	.ec table.details td { padding: 4px 12px 4px 0; vertical-align: top; }
	.ec table.details td:first-child { color: #6b7280; width: 35%; }
	.ec h4 { margin-top: 24px; }
</style>
<div class="ec">
	<h2>Enterprise Warranty Contract</h2>
	<div class="muted">{{ doc.name }} · {{ doc.status }}</div>

	<h4>Customer</h4>
	<table class="details">
		<tr><td>Billing Name</td><td>{{ doc.billing_name or "" }}</td></tr>
		{%- if address %}
		<tr><td>Billing Address</td><td>
			{{ address.address_line1 or "" }}{% if address.address_line2 %}, {{ address.address_line2 }}{% endif %}<br>
			{{ address.city or "" }}{% if address.state %}, {{ address.state }}{% endif %} {{ address.pincode or "" }}<br>
			{{ address.country or "" }}
			{%- if address.gstin and address.gstin != "Not Applicable" %}<br>GSTIN: {{ address.gstin }}{% endif %}
		</td></tr>
		{%- endif %}
		<tr><td>Billing Email</td><td>{{ doc.billing_email or "" }}</td></tr>
		{%- if doc.contact_person %}
		<tr><td>Contact Person</td><td>{{ doc.contact_person }}{% if doc.designation %}, {{ doc.designation }}{% endif %}</td></tr>
		{%- endif %}
		{%- if doc.billing_partner %}
		<tr><td>Billing Partner</td><td>{{ doc.billing_partner }}</td></tr>
		{%- endif %}
		{%- if doc.legal_entities_covered %}
		<tr><td>Legal Entities Covered</td><td>{{ doc.legal_entities_covered | e | replace("\n", "<br>") }}</td></tr>
		{%- endif %}
	</table>

	<h4>Plan</h4>
	<table class="details">
		<tr><td>Plan</td><td>{{ doc.plan_title or doc.plan }}</td></tr>
		<tr><td>Yearly Price</td><td>{{ doc.get_formatted("yearly_price") }} (before tax)</td></tr>
		<tr><td>Start Date</td><td>{{ doc.get_formatted("start_date") }}</td></tr>
		<tr><td>Price Lock</td><td>{{ doc.price_lock_years }} year(s), until {{ doc.get_formatted("price_locked_until") }}</td></tr>
		{%- if doc.agreement_date %}
		<tr><td>Agreement Date</td><td>{{ doc.get_formatted("agreement_date") }}</td></tr>
		{%- endif %}
	</table>

	{%- if doc.payments %}
	<h4>Payments</h4>
	<table class="table table-bordered">
		<thead>
			<tr>
				<th>Period</th>
				<th class="text-right">Amount</th>
				<th class="text-right">Tax</th>
				<th class="text-right">Paid</th>
				<th>Reference</th>
				<th>Tax Invoice</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in doc.payments %}
			<tr>
				<td>{{ row.get_formatted("period_start") }} to {{ row.get_formatted("period_end") }}</td>
				<td class="text-right">{{ row.get_formatted("amount", doc) }}</td>
				<td class="text-right">{{ row.get_formatted("gst", doc) }}{% if row.gst_split %}<br><span class="muted">{{ {"intra_state": "CGST + SGST", "inter_state": "IGST"}.get(row.gst_split, "") }}</span>{% endif %}</td>
				<td class="text-right">{{ row.get_formatted("amount_paid", doc) }}</td>
				<td>{{ row.payment_reference or "" }}</td>
				<td>{{ row.frappe_invoice or "" }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>
	{%- endif %}
</div>
